// Get the incoming phone number from WhatsApp
const whatsappData = $('WhatsApp Trigger').first().json;

// Check if messages array exists
if (!whatsappData.messages || !Array.isArray(whatsappData.messages) || !whatsappData.messages[0]) {
  return [{
    json: {
      authorized: false,
      reason: 'WhatsApp message data not found',
      whatsappData: whatsappData
    }
  }];
}

const incomingPhone = whatsappData.messages[0].from;
const incomingBody = whatsappData.messages[0].text?.body || '';
const incomingBodyType = whatsappData.messages[0].type;

// Clean the incoming phone (remove all non-numeric characters)
const cleanIncomingPhone = incomingPhone.replace(/[^0-9]/g, '');

// Get all documents from MongoDB
const allDocs = $input.all();

// Debug: Log what we're searching for
console.log('Incoming phone (raw):', incomingPhone);
console.log('Incoming phone (cleaned):', cleanIncomingPhone);
console.log('Total documents from DB:', allDocs.length);

// Find if any document has a matching phone number
let isAuthorized = false;
let matchedPhone = null;
let matchedDoc = null;

for (const item of allDocs) {
  const doc = item.json;

  // Debug: Log each document's phone field
  if (doc.phoneNumber) {
    console.log('Checking DB phone:', doc.phoneNumber);
  }

  // Check all properties in the document for phone-like field names
  for (const [key, value] of Object.entries(doc)) {
    const fieldName = key.toLowerCase();

    // Check if this is a phone field
    if (fieldName.includes('phone') || fieldName.includes('mobile') || fieldName.includes('contact')) {

      if (value) {
        // Clean DB phone number (remove all non-numeric characters)
        const dbPhone = value.toString().replace(/[^0-9]/g, '');

        console.log(`Comparing: DB="${dbPhone}" vs Incoming="${cleanIncomingPhone}"`);

        // Try multiple comparison methods
        // Method 1: Last 10 digits
        if (dbPhone.length >= 10 && cleanIncomingPhone.length >= 10) {
          if (dbPhone.slice(-10) === cleanIncomingPhone.slice(-10)) {
            isAuthorized = true;
            matchedPhone = value;
            matchedDoc = doc;
            console.log('✅ Match found (last 10 digits)!');
            break;
          }
        }

        // Method 2: Exact match after cleaning
        if (dbPhone === cleanIncomingPhone) {
          isAuthorized = true;
          matchedPhone = value;
          matchedDoc = doc;
          console.log('✅ Match found (exact)!');
          break;
        }

        // Method 3: Check if one contains the other
        if (dbPhone.includes(cleanIncomingPhone) || cleanIncomingPhone.includes(dbPhone)) {
          isAuthorized = true;
          matchedPhone = value;
          matchedDoc = doc;
          console.log('✅ Match found (contains)!');
          break;
        }
      }
    }
  }

  if (isAuthorized) break;
}

return [{
  json: {
    authorized: isAuthorized,
    incomingPhone: incomingPhone,
    incomingPhoneCleaned: cleanIncomingPhone,
    incomingBody: incomingBody,
    incomingBodyType: incomingBodyType,
    matchedPhone: matchedPhone,
    matchedName: matchedDoc?.name || null,
    debugInfo: {
      totalDocsChecked: allDocs.length,
      rawIncoming: incomingPhone,
      cleanedIncoming: cleanIncomingPhone
    }
  }
}];

// Get the data from previous node
const inputData = $input.item.json;

// Build the update object with ONLY fields that have actual values
const updateFields = {};

// List of fields that can be updated
const allowedFields = ['name', 'designation', 'workingKnowledge', 'email', 'lastMessage', 'lastMessageDate', 'updatedAt'];

// Only include fields that have actual values (not undefined, not null, not empty string)
allowedFields.forEach(field => {
  if (inputData[field] !== undefined && 
      inputData[field] !== null && 
      inputData[field] !== '') {
    updateFields[field] = inputData[field];
  }
});

// IMPORTANT: Create a comma-separated list of field names for MongoDB
const fieldsList = Object.keys(updateFields).join(',');

// Return formatted data for MongoDB with dynamic field list
return {
  json: {
    phoneNumber: inputData.phoneNumber,
    responseMessage: inputData.responseMessage,
    fieldsToUpdate: fieldsList,  // This will be used in MongoDB node
    ...updateFields
  }
};
